bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
docker exec -i "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
setDefaultResultOrder('ipv4first');
setDefaultAutoSelectFamily(false);
const e=process.env;
const pass=readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim();
const url='postgresql://'+encodeURIComponent(e.VIDEOBOT_DB_USER)+':'+encodeURIComponent(pass)+'@'+e.VIDEOBOT_DB_HOST+':5432/'+e.VIDEOBOT_DB_NAME;
const pool=new pg.Pool({connectionString:url,max:1,connectionTimeoutMillis:5000});
const listingId='389558ba-a38b-42a1-b92e-e98143df3e2d';
try{
  const result=await pool.query(
    "SELECT r.status AS receipt_status,r.free_message_ids,r.paid_message_id,l.status AS listing_status,l.price_stars FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id WHERE r.listing_id=$1 AND r.revision=1 AND r.status='sent' AND l.status='published'",
    [listingId]);
  if(result.rowCount!==1)throw Error('POST_RECEIPT_NOT_UNIQUE');
  const x=result.rows[0],free=x.free_message_ids?.map(Number);
  if(x.price_stars!==10||free?.length!==2||free[0]!==4689||free[1]!==4690||Number(x.paid_message_id)!==4691)throw Error('PAID_MEDIA_IDENTITY_MISMATCH');
  if(e.VIDEOBOT_VIDEO_SALE_THREAD_ID!=='1695')throw Error('PAID_MEDIA_TOPIC_MISMATCH');
  const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
  const api=createTelegramBotApi({token,timeoutMs:25000,baseUrl:e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
  const updated=await api('editMessageReplyMarkup',{
    chat_id:-1002373696859,
    message_id:4689,
    reply_markup:{inline_keyboard:[[{
      text:'⭐ Stars本編・購入はこちら',
      url:'https://t.me/c/2373696859/4691'
    }]]}
  });
  if(updated!==true&&updated?.message_id!==4689)throw Error('PREVIEW_LINK_ACK_INVALID');
  console.log('FREE_ALBUM_TO_PAID_MEDIA_LINK=PASS');
  console.log('LINK_SOURCE_MESSAGE=4689');
  console.log('LINK_DEST_MESSAGE=4691');
}finally{await pool.end()}
NODE
